import { useI18n } from '@gntik-ai/ui';
import {
  DataTable,
  NoResultsEmpty,
  PageHeader,
  PageToolbar,
  ResourceCardGrid,
  type ResourceAction,
  type ResourceCard,
} from '@gntik-ai/blocks';
import { Plus } from '@gntik-ai/icons';
import { Page, Stack, type BreadcrumbItem } from '@gntik-ai/ui';
import { useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { galleryBreadcrumbs, galleryColumns, galleryItems, galleryViews, searchResources } from './data';

export type GalleryView = 'grid' | 'table';

export interface ResourceGalleryProps {
  title: string;
  description: string;
  breadcrumbs: BreadcrumbItem[];
  /** Initial cards; the page keeps its own copy so the demo Delete takes effect. */
  items: readonly ResourceCard[];
  defaultView: GalleryView;
  onViewChange: (view: GalleryView) => void;
  createLabel: string;
  onCreate: () => void;
  /** Card menu actions. Without it, Delete removes the card locally. */
  onAction: (action: ResourceAction, item: ResourceCard) => void;
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Resource gallery: toolbar with search and a grid/table view toggle over the same resources. */
export default function ResourceGalleryPage({
  title = 'Resources',
  description = 'Services, databases and jobs that make up this project.',
  breadcrumbs = galleryBreadcrumbs,
  items: initialItems = galleryItems,
  defaultView = 'grid',
  onViewChange,
  createLabel = 'New resource',
  onCreate,
  onAction,
  shell,
}: Partial<ResourceGalleryProps>) {
  const { locale } = useI18n();
  const [items, setItems] = useState<readonly ResourceCard[]>(initialItems);
  const [view, setView] = useState<GalleryView>(defaultView);
  const [query, setQuery] = useState('');
  const visible = searchResources(items, query, locale);

  const handleAction = (action: ResourceAction, item: ResourceCard) => {
    if (onAction) onAction(action, item);
    else if (action === 'delete') setItems((prev) => prev.filter((i) => i.id !== item.id));
  };

  return (
    <ConsoleShell currentHref="/projects" breadcrumbs={breadcrumbs} {...shell}>
      <Page
        width="wide"
        header={
          <PageHeader
            breadcrumbs={null}
            title={title}
            description={description}
            status=""
            meta={[]}
            tabs={null}
            actions={[]}
          />
        }
      >
        <Stack gap={5}>
          <PageToolbar
            aria-label="Resources toolbar"
            search={query}
            onSearchChange={setQuery}
            searchLabel="Search resources"
            searchPlaceholder="Search resources…"
            // PageToolbar falls back to a "Filters" button for null/undefined; an empty fragment hides it.
            filters={<></>}
            views={galleryViews}
            view={view}
            onViewChange={(next) => {
              const v: GalleryView = next === 'table' ? 'table' : 'grid';
              setView(v);
              onViewChange?.(v);
            }}
            primaryAction={{ label: createLabel, icon: Plus, onClick: onCreate }}
          />
          <Stack gap={3}>
            <p aria-live="polite" className="text-[12.5px] text-muted-foreground">
              {visible.length} of {items.length} shown
            </p>
            {visible.length === 0 ? (
              <NoResultsEmpty
                entity="resources"
                query={query}
                filterCount={0}
                onClearSearch={() => setQuery('')}
                titleAs="h2"
                bordered
              />
            ) : view === 'grid' ? (
              <ResourceCardGrid items={visible} label="Resources" onAction={handleAction} titleAs="h2" />
            ) : (
              <DataTable<ResourceCard>
                rows={visible}
                columns={galleryColumns}
                caption="Resources"
                selectable={false}
                paginated={false}
                showDensityToggle={false}
                rowActions={(item) => [
                  { label: 'Open', onSelect: () => handleAction('open', item) },
                  'separator',
                  { label: 'Delete', destructive: true, onSelect: () => handleAction('delete', item) },
                ]}
              />
            )}
          </Stack>
        </Stack>
      </Page>
    </ConsoleShell>
  );
}

import { matchText } from '@gntik-ai/ui';
import { RESOURCE_CARDS, type DataTableColumn, type PageToolbarView, type ResourceCard } from '@gntik-ai/blocks';
import { LayoutGrid, Table2 } from '@gntik-ai/icons';
import { StatusTag, type BreadcrumbItem } from '@gntik-ai/ui';
import { createElement } from 'react';

export const galleryItems: ResourceCard[] = RESOURCE_CARDS;

export const galleryBreadcrumbs: BreadcrumbItem[] = [
  { label: 'Overview', href: '/overview' },
  { label: 'Projects', href: '/projects' },
  { label: 'Resources' },
];

export const galleryViews: PageToolbarView[] = [
  { value: 'grid', label: 'Grid view', icon: LayoutGrid },
  { value: 'table', label: 'Table view', icon: Table2 },
];

/** Table columns for the same cards (the alternate view). */
export const galleryColumns: DataTableColumn<ResourceCard>[] = [
  { id: 'name', header: 'Name', accessor: (r) => r.name, sortable: true, hideable: false, className: 'font-semibold' },
  { id: 'description', header: 'Description', accessor: (r) => r.description, className: 'text-muted-foreground' },
  {
    id: 'status',
    header: 'Status',
    accessor: (r) => r.status,
    cell: (r) => (r.status ? createElement(StatusTag, { status: r.status }) : null),
    sortable: true,
  },
  {
    id: 'cost',
    header: 'Cost 30d',
    accessor: (r) => r.meta?.find((m) => m.label === 'Cost 30d')?.value,
    align: 'right',
    className: 'font-mono text-[12.5px]',
  },
];

/** Case-insensitive search over name and description. */
export function searchResources(items: readonly ResourceCard[], query: string, locale?: string): ResourceCard[] {
  return items.filter((i) => matchText(i.name, query, { locale }) || matchText(i.description ?? '', query, { locale }));
}

import { ChartLocaleProvider } from '@gntik-ai/charts';
import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import {
  SidebarLayout,
  useI18n,
  type BreadcrumbItem,
  type NavGroup,
  type SidebarLayoutProps,
  type UserMenuUser,
  type Workspace,
} from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends
    Omit<AppSidebarHeaderProps, 'collapsed' | 'className' | 'workspaces'>,
    Pick<
      AppSidebarFooterProps,
      'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'userMenuChildren' | 'onSignOut'
    >,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  userMenuChildren,
  brand,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
  ...contextProps
}: ConsoleShellProps) {
  const { locale } = useI18n();
  return (
    <ChartLocaleProvider locale={locale}>
      <SidebarLayout
        fullScreen
        storageKey={storageKey}
        sidebarLabel={sidebarLabel}
        collapseMode={collapseMode}
        sidebarHeader={({ collapsed }) => (
          <AppSidebarHeader
            collapsed={collapsed}
            workspaces={workspaces}
            currentWorkspaceId={currentWorkspaceId}
            onWorkspaceChange={onWorkspaceChange}
            onCreateWorkspace={onCreateWorkspace}
            brand={brand}
            {...contextProps}
          />
        )}
        sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
        sidebarFooter={({ collapsed }) => (
          <AppSidebarFooter
            collapsed={collapsed}
            user={user}
            usage={usage}
            helpHref={helpHref}
            helpLabel={helpLabel}
            userMenuItems={userMenuItems}
            userMenuChildren={userMenuChildren}
            onSignOut={onSignOut}
          />
        )}
        topbar={
          brand == null ? (
            <AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />
          ) : (
            <>
              <div className="min-w-0 shrink-0 lg:hidden">{brand}</div>
              <AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />
            </>
          )
        }
      >
        {children}
      </SidebarLayout>
    </ChartLocaleProvider>
  );
}
